Translate the following GNU C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include<bits/stdc++.h>
using namespace std;

int n, t;
int cap[400][400];
char sci[20][20], rec[20][20];
int dist[15][15][15][15];
int dx[] = {1,0,-1,0};
int dy[] = {0,1,0,-1};
int seenA[13][13], seenB[13][13];
int level[400], ptr[400];

inline int getnode(int x,int y) { return (x-1)*n + y - 1; }

void spread(int val) {
    for (int i=1; i<=n; ++i)
        for (int j=1; j<=n; ++j)
            seenB[i][j] = seenA[i][j];
    for (int i=1; i<=n; ++i) {
        for (int j=1; j<=n; ++j) {
            if (seenB[i][j] == val) {
                for (int k=0; k<4; ++k) {
                    int ni=i+dx[k], nj=j+dy[k];
                    if (ni>0 && nj>0 && ni<=n && nj<=n && seenB[ni][nj] < val && sci[ni][nj] != 'Y')
                        seenA[ni][nj] = val;
                }
            }
        }
    }
}

bool reachable(int sx,int sy,int tx,int ty,int ix,int iy) {
    memset(seenA, 0, sizeof(seenA));
    seenA[sx][sy] = 1;
    seenA[ix][iy] = 2;
    for (int step=0; step<100; ++step) {
        spread(1);
        if (seenA[tx][ty] == 1) return true;
        spread(2);
        if (seenA[tx][ty] == 2) return false;
    }
    return false;
}

bool make_level_graph(int src, int sink) {
    memset(level, -1, sizeof(level));
    queue<int> q;
    level[src] = 0;
    q.push(src);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v=0; v<=sink; ++v) {
            if (level[v] == -1 && cap[u][v] > 0) {
                level[v] = level[u] + 1;
                q.push(v);
            }
        }
    }
    return level[sink] != -1;
}

int dinic_dfs(int u, int sink, int pushed) {
    if (u == sink) return pushed;
    for (int &v = ptr[u]; v <= sink; ++v) {
        if (cap[u][v] > 0 && level[v] == level[u] + 1) {
            int got = dinic_dfs(v, sink, min(pushed, cap[u][v]));
            if (got) {
                cap[u][v] -= got;
                cap[v][u] += got;
                return got;
            }
        }
    }
    return 0;
}

int main() {
    memset(dist, 1, sizeof(dist));
    cin >> n >> t;
    int infx=0, infy=0;
    for (int i=1; i<=n; ++i) {
        cin >> (sci[i]+1);
        for (int j=1; j<=n; ++j) {
            dist[i][j][i][j] = 0;
            if (sci[i][j] == 'Z') { infx=i; infy=j; }
        }
    }
    for (int i=1; i<=n; ++i) cin >> (rec[i]+1);
    for (int i=1; i<=n; ++i)
        for (int j=1; j<=n; ++j)
            for (int k=0; k<4; ++k) {
                int ni=i+dx[k], nj=j+dy[k];
                if (ni>0 && ni<=n && nj>0 && nj<=n && sci[i][j]!='Y' && sci[ni][nj]!='Y')
                    dist[i][j][ni][nj] = 1;
            }
    for (int kx=1; kx<=n; ++kx)
        for (int ky=1; ky<=n; ++ky)
            for (int sx=1; sx<=n; ++sx)
                for (int sy=1; sy<=n; ++sy)
                    for (int tx=1; tx<=n; ++tx)
                        for (int ty=1; ty<=n; ++ty)
                            dist[sx][sy][tx][ty] = min(dist[sx][sy][tx][ty],
                                                       dist[sx][sy][kx][ky] + dist[kx][ky][tx][ty]);
    int src = 2*n*n + 1, sink = 2*n*n + 2;
    for (int i=1; i<=n; ++i)
        for (int j=1; j<=n; ++j) {
            if (isdigit(sci[i][j])) cap[src][getnode(i,j)] = sci[i][j] - '0';
            if (isdigit(rec[i][j])) cap[n*n + getnode(i,j)][sink] = rec[i][j] - '0';
            if (isdigit(sci[i][j])) {
                for (int a=1; a<=n; ++a)
                    for (int b=1; b<=n; ++b) {
                        if (sci[i][j] > '0' && rec[a][b] > '0' && isdigit(rec[a][b]) &&
                            dist[i][j][a][b] <= t && reachable(i,j,a,b,infx,infy))
                            cap[getnode(i,j)][n*n + getnode(a,b)] = 1000;
                    }
            }
        }
    int answer = 0;
    while (make_level_graph(src, sink)) {
        for (int i=0; i<=sink; ++i) ptr[i] = 0;
        int f;
        while ((f = dinic_dfs(src, sink, 1000000000)) > 0) {
            answer += f;
        }
    }
    cout << answer << '\n';
    return 0;
}
